/* ===== 纯函数区（首个无属性 script）：可被 Node _test.js 提取并断言 ===== */
  function esc(s){ return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
  function num(v){ var n=parseFloat(String(v==null?'':v).replace(/,/g,'')); return isNaN(n)?NaN:n; }
  function detectDelimiter(text){
    var first = (text.split(/\r?\n/)[0]||'');
    var c=(first.match(/,/g)||[]).length, t=(first.match(/\t/g)||[]).length, s=(first.match(/;/g)||[]).length;
    if (t>=c && t>=s && t>0) return '\t';
    if (s>=c && s>0) return ';';
    return ',';
  }
  function parseDelimited(text, delim, quote){
    delim = delim || ','; quote = (quote==null)?'"':quote;
    var rows=[], row=[], field='', i=0, n=text.length, q=false;
    while(i<n){
      var ch=text[i];
      if(q){
        if(ch===quote){ if(text[i+1]===quote){ field+=quote; i+=2; continue; } q=false; i++; continue; }
        field+=ch; i++; continue;
      }
      if(ch===quote && field===''){ q=true; i++; continue; }
      if(ch===delim){ row.push(field); field=''; i++; continue; }
      if(ch==='\n'||ch==='\r'){ if(ch==='\r'&&text[i+1]==='\n') i++; row.push(field); rows.push(row); row=[]; field=''; i++; continue; }
      field+=ch; i++;
    }
    if(field!=='' || row.length>0){ row.push(field); rows.push(row); }
    while(rows.length && rows[rows.length-1].length===1 && rows[rows.length-1][0]==='') rows.pop();
    while(rows.length && rows[rows.length-1].every(function(x){return x==='';})) rows.pop();
    return rows;
  }
  function toDelimited(rows, delim, quote){
    delim = delim || ','; quote = (quote==null)?'"':quote;
    return rows.map(function(r){
      return r.map(function(cell){
        var s=String(cell==null?'':cell);
        if(s.indexOf(delim)>=0 || s.indexOf(quote)>=0 || s.indexOf('\n')>=0 || s.indexOf('\r')>=0){
          return quote + s.split(quote).join(quote+quote) + quote;
        }
        return s;
      }).join(delim);
    }).join('\n');
  }
  function toMarkdown(rows){
    if(!rows.length) return '';
    function cells(r){ return '| ' + r.map(function(c){return String(c==null?'':c).trim();}).join(' | ') + ' |'; }
    var head = cells(rows[0]);
    var sep = '| ' + rows[0].map(function(){return '---';}).join(' | ') + ' |';
    var body = rows.slice(1).map(cells).join('\n');
    return head + '\n' + sep + (body ? '\n' + body : '');
  }
  function toHTML(rows){
    if(!rows.length) return '<table></table>';
    var head = rows[0].map(function(c){return '<th>'+esc(c)+'</th>';}).join('');
    var body = rows.slice(1).map(function(r){ return '<tr>'+r.map(function(c){return '<td>'+esc(c)+'</td>';}).join('')+'</tr>'; }).join('');
    return '<table border="1" cellspacing="0" cellpadding="6"><thead><tr>'+head+'</tr></thead><tbody>'+body+'</tbody></table>';
  }
  function toJSON(rows){
    if(!rows.length) return '[]';
    var header = rows[0];
    var objs = rows.slice(1).map(function(r){
      var o={}; header.forEach(function(h,i){ o[String(h).trim()] = (r[i]==null?'':r[i]); }); return o;
    });
    return JSON.stringify(objs, null, 2);
  }
  function transpose(rows){
    if(!rows.length) return [];
    var cols = Math.max.apply(null, rows.map(function(r){return r.length;}));
    var out=[];
    for(var c=0;c<cols;c++){ var nr=[]; for(var ri=0;ri<rows.length;ri++){ nr.push(rows[ri][c]==null?'':rows[ri][c]); } out.push(nr); }
    return out;
  }
  function sortRows(rows, colIdx, dir, hasHeader){
    if(!rows.length) return rows;
    var head = hasHeader ? rows[0] : null;
    var body = (hasHeader ? rows.slice(1) : rows.slice()).map(function(r){return r.slice();});
    var mul = dir==='desc' ? -1 : 1;
    body.sort(function(a,b){
      var va=num(a[colIdx]), vb=num(b[colIdx]);
      if(!isNaN(va)&&!isNaN(vb)) return (va-vb)*mul;
      var sa=String(a[colIdx]==null?'':a[colIdx]).toLowerCase();
      var sb=String(b[colIdx]==null?'':b[colIdx]).toLowerCase();
      return sa.localeCompare(sb)*mul;
    });
    return hasHeader ? [head].concat(body) : body;
  }
  function filterRows(rows, colIdx, query, hasHeader){
    if(!rows.length) return [];
    var q=String(query).toLowerCase(), out=[];
    for(var i=0;i<rows.length;i++){
      if(hasHeader && i===0){ out.push(rows[i]); continue; }
      var cell=String(rows[i][colIdx]==null?'':rows[i][colIdx]).toLowerCase();
      if(cell.indexOf(q)>=0) out.push(rows[i]);
    }
    return out;
  }
  function aggregate(rows, groupCol, valCol, op, hasHeader){
    if(!rows.length) return [];
    var body = hasHeader ? rows.slice(1) : rows;
    var groups={};
    body.forEach(function(r){ var g=String(r[groupCol]==null?'':r[groupCol]); (groups[g]=groups[g]||[]).push(num(r[valCol])); });
    var out=[];
    Object.keys(groups).forEach(function(g){
      var vals=groups[g].filter(function(v){return !isNaN(v);});
      var res;
      if(op==='count') res=groups[g].length;
      else if(op==='sum') res=vals.reduce(function(a,b){return a+b;},0);
      else if(op==='avg') res= vals.length ? vals.reduce(function(a,b){return a+b;},0)/vals.length : 0;
      else if(op==='min') res= vals.length ? Math.min.apply(null,vals) : 0;
      else if(op==='max') res= vals.length ? Math.max.apply(null,vals) : 0;
      else res=vals.length;
      out.push([g, res]);
    });
    return out;
  }
  function columnStats(values){
    var nums = values.map(num).filter(function(v){return !isNaN(v);});
    var nonempty = values.filter(function(v){return String(v==null?'':v).trim()!=='';}).length;
    var sum = nums.reduce(function(a,b){return a+b;},0);
    return { count:values.length, nonempty:nonempty,
      min: nums.length?Math.min.apply(null,nums):NaN,
      max: nums.length?Math.max.apply(null,nums):NaN,
      sum:sum, avg: nums.length? sum/nums.length : NaN };
  }
  if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
      esc:esc, num:num, detectDelimiter:detectDelimiter, parseDelimited:parseDelimited,
      toDelimited:toDelimited, toMarkdown:toMarkdown, toHTML:toHTML, toJSON:toJSON,
      transpose:transpose, sortRows:sortRows, filterRows:filterRows, aggregate:aggregate, columnStats:columnStats
    };
  }
if (typeof window !== 'undefined') {
  window.TableForgePure = {
    esc:esc, num:num, detectDelimiter:detectDelimiter, parseDelimited:parseDelimited,
    toDelimited:toDelimited, toMarkdown:toMarkdown, toHTML:toHTML, toJSON:toJSON,
    transpose:transpose, sortRows:sortRows, filterRows:filterRows, aggregate:aggregate, columnStats:columnStats
  };
}
